args<-commandArgs(trailingOnly=TRUE);Sys.setenv(PHASE1RR_ROOT=normalizePath(args[1]));source(file.path(Sys.getenv('PHASE1RR_ROOT'),'10_code/phase1rr_common.R'));rows<-list()
for(cid in c('mTKO_4T1_T25','mTKO_B16_T17','mTKO_MC38_T15')){xx<-read_contrast(cid);perm<-combn(1:6,3);scoremat<-NULL;effmat<-NULL;gn<-NULL
 for(k in 1:20){labs<-as.integer(1:6 %in% perm[,k]);fit<-fit_dataset(xx$counts,xx$keep,xx$gene,labels=labs);g<-fit$gene;if(is.null(gn))gn<-g$gene;stopifnot(identical(gn,g$gene));scoremat<-cbind(scoremat,g$PRIMARY_GENE_SCORE);effmat<-cbind(effmat,g$median_log2FC);rows[[length(rows)+1]]<-data.table(contrast=cid,assignment=paste(colnames(xx$counts)[perm[,k]],collapse=','),observed_labels=identical(labs,c(0L,0L,0L,1L,1L,1L)),n_genes=nrow(g),abs_score_q99=quantile(abs(g$PRIMARY_GENE_SCORE),.99),abs_effect_q99=quantile(abs(g$median_log2FC),.99),n_abs_effect_gt_0_5=sum(abs(g$median_log2FC)>.5),n_abs_effect_gt_1=sum(abs(g$median_log2FC)>1),diagnostic_only=TRUE)
 };colnames(scoremat)<-apply(perm,2,function(i)paste(colnames(xx$counts)[i],collapse=','));colnames(effmat)<-colnames(scoremat);saveRDS(list(gene=gn,scores=scoremat,effects=effmat),file.path(O,paste0(cid,'.PRIMARY_SCORE_EXACT20.rds')),compress=FALSE);cat('DONE EXACT20',cid,'\n');flush.console()
}
z<-rbindlist(rows);z[,observed_abs_score_q99_rank:=sum(abs_score_q99>abs_score_q99[observed_labels]+1e-9)+1,by=contrast];z[,observed_abs_effect_q99_rank:=sum(abs_effect_q99>abs_effect_q99[observed_labels]+1e-9)+1,by=contrast];write_tsv(z,file.path(Q,'PRIMARY_SCORE_EXACT20.tsv'))
